mapper.sql:
FROM place WHERE status = 'public'
AND category = #{category}
AND (name ILIKE #{pattern} ESCAPE '\' OR description ILIKE #{pattern} ESCAPE '\' OR address ILIKE #{pattern} ESCAPE '\')

mapper.select:
SELECT slug, name, category, subtype, address, image_url, latitude, longitude, opening_hours,
round(distance)::int NULL::int AS distance_m FROM ( SELECT id, slug, name, category, subtype, address, image_url, opening_hours, ST_Y(location::geometry) AS latitude, ST_X(location::geometry) AS longitude, ST_Distance(location, ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography) AS distance
) AS found ORDER BY distance, id LIMIT #{limit} OFFSET #{offset}
